import string

ALPHABET = string.ascii_lowercase
M = len(ALPHABET)


def _check_coprime(a):
    if _gcd(a, M) != 1:
        raise ValueError("a and m must be coprime.")


def _gcd(x, y):
    while y:
        x, y = y, x % y
    return x


def _modular_inverse(a):
    for x in range(M):
        if (a * x) % M == 1:
            return x
    raise ValueError("a and m must be coprime.")


def _encode_char(ch, a, b):
    i = ALPHABET.index(ch)
    return ALPHABET[(a * i + b) % M]


def _decode_char(ch, a_inv, b):
    y = ALPHABET.index(ch)
    return ALPHABET[(a_inv * (y - b)) % M]


def encode(plain_text, a, b):
    _check_coprime(a)
    result = []
    for ch in plain_text.lower():
        if ch in ALPHABET:
            result.append(_encode_char(ch, a, b))
        elif ch.isdigit():
            result.append(ch)
    grouped = ["".join(result[i:i + 5]) for i in range(0, len(result), 5)]
    return " ".join(grouped)


def decode(ciphered_text, a, b):
    _check_coprime(a)
    a_inv = _modular_inverse(a)
    result = []
    for ch in ciphered_text.lower():
        if ch in ALPHABET:
            result.append(_decode_char(ch, a_inv, b))
        elif ch.isdigit():
            result.append(ch)
    return "".join(result)

